effect.shader:
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    vec2 u = f*f*(3.0-2.0*f);
    return mix(mix(a,b,u.x), mix(c,d,u.x), u.y);
}

void main() {
    float t = acTime * speed;
    vec2 off = vec2(
        noise(acScreenNorm * freq + vec2(t, 0.0)) - 0.5,
        noise(acScreenNorm * freq + vec2(0.0, t * 1.3)) - 0.5
    ) * 2.0 * amp;

    vec2 uv = acScreenNorm + off;
    vec4 s = vec4(0.0);
    for (int i = -2; i <= 2; i++)
        s += texture(inputImg, uv + vec2(float(i), 0.0) * blur * 0.5);
    for (int i = -2; i <= 2; i++)
        s += texture(inputImg, uv + vec2(0.0, float(i)) * blur * 0.5);
    fragColor = s / 10.0;
}
